import base64
import os
# -*- coding: utf-8 -*-
import subprocess
import time
from datetime import datetime

from ta_ue_plugin_android.uepc.android_control import AndroidControl


class SoundcardAndroidControl(AndroidControl):
    """Controlling UE or devices that cooperate with it"""

    def __init__(self, special_name_sufix=''):
        """
        Soundcard Android Control

        :param special_name_sufix: used only to create log file on UE PC
        """
        super(SoundcardAndroidControl, self).__init__(special_name_sufix=special_name_sufix)
        self.logger.debug("SoundcardAndroidControl instance created (also shows how to log in this class)")

    def ip_show_addr(self):
        """
        Show IP address.

        :return:
        """
        # this code runs on UE PC
        return subprocess.Popen("ip addr show", shell=True, stdout=subprocess.PIPE, bufsize=1, universal_newlines=True).stdout.read()

    # speech path check
    def _play_on_soundcard(self, output_soundcard, wav_file='0to9sh'):
        self.logger.info('Playing on soundcard "{}"'.format(output_soundcard))
        curr_dir = os.getcwd()
        subprocess.Popen('aplay --device=sysdefault:CARD={} {}/{}.wav&'.format(output_soundcard, curr_dir, wav_file),
                         shell=True, stdout=subprocess.PIPE,
                         stderr=subprocess.STDOUT,
                         bufsize=1, universal_newlines=True)

    def _record_on_soundcard(self, soundcard, scope='_init', duration=5):
        self.logger.info('Recording on soundcard "{}"'.format(soundcard))
        subprocess.Popen("amixer -c {} set Line 90% on".format(soundcard), shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, bufsize=1,
                         universal_newlines=True).communicate()
        recorded_filename = "{}/audiofiles/{}{}.wav".format(os.getcwd(), soundcard, scope)
        arecord_cmd_template = "arecord --format=S16_LE --channels=1 --rate=8000 --duration={} --device=sysdefault:CARD={} {}"
        subprocess.Popen(arecord_cmd_template.format(duration, soundcard, recorded_filename), shell=True, stdout=subprocess.PIPE,
                         stderr=subprocess.STDOUT, bufsize=1, universal_newlines=True)
        time.sleep(float(duration))
        self.logger.info('Finished recording on soundcard "{}"'.format(soundcard))
        return recorded_filename

    def speech_path_check_on_ue(self, soundcard_calling, soundcard_called):
        """
        :param soundcard_calling:
        :param soundcard_called:
        :return:
        """
        if not soundcard_called or not soundcard_calling:
            raise Exception(
                'Soundcard(s) not defined in config file! Calling party soundcard: {}, Called party soundcard: {}'.format(
                    soundcard_calling, soundcard_called))
        self._empty_directory('{}/audiofiles'.format(os.getcwd()))
        self._play_on_soundcard(soundcard_calling)

        date = datetime.now().strftime('%Y-%m-%d-%H-%M-%S')
        recorded_filename = self._record_on_soundcard(soundcard_called, "_spc_{}".format(date), 10)
        with open(recorded_filename, 'rb') as f:
            file_name = f.name
            file_data = f.read()

        return file_name, base64.b64encode(file_data)

    def record_on_ue(self, duration, scope, soundcard_name):
        """
        :param duration:
        :param scope:
        :param soundcard_name:
        :return:
        """
        self._empty_directory(os.path.join(os.getcwd(), 'audiofiles'))
        date = datetime.now().strftime('%Y-%m-%d-%H-%M-%S')
        scope = '_record_{}_{}'.format(scope, date)
        recorded_filename = self._record_on_soundcard(soundcard_name, scope, duration)

        with open(recorded_filename, 'rb') as f:
            file_name = f.name
            file_data = f.read()

        return file_name, base64.b64encode(file_data)

    @staticmethod
    def _empty_directory(path):
        if os.path.isdir(path):
            filelist = os.listdir(path)
            for filename in filelist:
                os.remove('{}/{}'.format(path, filename))
        else:
            os.mkdir(path)
